import{_ as a,o,c as t,ah as r}from"./chunks/framework.D4KxWb5R.js";const p=JSON.parse('{"title":"My account","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/account.md","filePath":"src/en/guide/account.md"}'),i={name:"en/guide/account.md"};function n(s,e,h,c,d,l){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="my-account" tabindex="-1">My account <a class="header-anchor" href="#my-account" aria-label="Permalink to &quot;My account&quot;">​</a></h1><p>Open the menu under your name, bottom left, then <strong>Settings</strong>. The settings have five tabs: Profile, Security, Notifications, Appearance and Language.</p><h2 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h2><p>Change your name and e-mail address, and add a profile photo. Changing your e-mail address requires confirming the new one through the link received.</p><p>Your position, scope and access are not changed here: they belong to the general administrator.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><h3 id="password" tabindex="-1">Password <a class="header-anchor" href="#password" aria-label="Permalink to &quot;Password&quot;">​</a></h3><p>Enter the current password, then the new one (at least 12 characters by default). Changing your password forgets all your remembered devices.</p><h3 id="authenticator-app" tabindex="-1">Authenticator app <a class="header-anchor" href="#authenticator-app" aria-label="Permalink to &quot;Authenticator app&quot;">​</a></h3><ol><li><strong>Enable 2FA</strong>, then confirm your password.</li><li>Scan the QR code with your app (or enter the setup key).</li><li>Enter the 6-digit code shown by the app.</li><li>Keep the <strong>recovery codes</strong> in a password manager: each one allows one sign-in if you lose your phone.</li></ol><p>Once the app is active, it gives you the sign-in code instead of the e-mail. <strong>Disable 2FA</strong> goes back to the e-mail code if two-factor authentication is required for you.</p><h3 id="passkeys" tabindex="-1">Passkeys <a class="header-anchor" href="#passkeys" aria-label="Permalink to &quot;Passkeys&quot;">​</a></h3><p><strong>Add passkey</strong> registers a passkey (fingerprint, face, phone PIN or security key) under a name of your choice. You then sign in without a password or code. Remove a passkey you no longer use.</p><h3 id="remembered-devices" tabindex="-1">Remembered devices <a class="header-anchor" href="#remembered-devices" aria-label="Permalink to &quot;Remembered devices&quot;">​</a></h3><p>The list shows the browsers on which you ticked &quot;Remember this device&quot; while entering a code received by e-mail: they don&#39;t ask for a code for 30 days. <strong>Forget</strong> removes a device; <strong>Forget all</strong> removes them all. Do it if you lose a device or used a shared computer.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>See <a href="./notifications.html#choosing-how-you-are-notified">Notifications</a>.</p><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2><p>Choose the light theme, the dark theme or your system&#39;s.</p><h2 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h2><p>Choose English or French. The language applies to the whole intranet, the M&#39;City back-office and your notifications.</p>',21)])])}const g=a(i,[["render",n]]);export{p as __pageData,g as default};
